/**
 * Create a capture schedule
 *
 * Creates a capture schedule for the caller's organization: a proof of funds is captured at every instant its cron names in its timezone, over its chains and tokens (empty means all), and its newest keep_last captures are kept. The cron is the five-field standard form; runs must be at least 5 minutes apart, and day of month and day of week cannot both be restricted. Every chain must hold one of the organization's active wallets, as its primary chain or as a network included in runs, and every token must be a token of the organization on a chain the capture reads. An organization has at most 10 schedules. Each validation failure is a 400 naming the field. Every run is planned a little after its target, as a read of the past, so every chain the captures read needs a provider that declares it can read balances 2 minutes back; a chain none can serve (every provider reads only the current block, cannot read token balances at a past block, or keeps too little history) is a 422 naming the chain and each provider's limit. A missed run is caught up only while the schedule's chains can still serve it: the catch-up window is the shallowest chain's history less a minute, at most an hour. The creator is the calling user, or the API key for API-key callers, and the response names it in created_by or created_by_api_key_id. The response carries the catch-up window in seconds (catchup_window_seconds) and the chain and provider that shorten it below an hour (catchup_limited_by, null when nothing does). The row is stored first and its workflow engine schedule created after; when the engine cannot create it, the row is removed again and the response is 503, so the caller may retry.
 */
export const postApiCaptureSchedules = <ThrowOnError extends boolean = false>(
  options: Options<PostApiCaptureSchedulesData, ThrowOnError>
) =>
  (options.client ?? client).post<
    PostApiCaptureSchedulesResponses,
    PostApiCaptureSchedulesErrors,
    ThrowOnError
  >({
    security: [{ name: 'Authorization', type: 'apiKey' }],
    url: '/api/capture-schedules',
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

